create table public.overtime_rules (
  id uuid not null default gen_random_uuid(),
  province_code text not null,
  province_name text not null,
  rule_name text not null,
  weekly_threshold_hours numeric(6,2),
  daily_threshold_hours numeric(6,2),
  alternate_daily_threshold_hours numeric(6,2),
  overtime_multiplier numeric(4,2) not null default 1.50,
  daily_overtime_enabled boolean not null default false,
  weekly_overtime_enabled boolean not null default true,
  requires_schedule_rule boolean not null default false,
  is_default boolean not null default true,
  is_active boolean not null default true,
  effective_from date not null,
  effective_to date,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  calculation_method text not null default 'weekly_only',
  double_time_threshold_hours numeric(6,2),
  double_time_multiplier numeric(4,2),
  holiday_week_threshold_hours numeric(6,2),
  supports_averaging boolean not null default false,
  rule_priority integer not null default 100,
  jurisdiction_type text not null default 'province',
  is_special_rule boolean not null default false,
  week_start_day integer not null default 0,
  holiday_rule text not null default 'none',
  holiday_reduction_hours numeric(6,2),
  constraint overtime_rules_pkey primary key (id),
  constraint overtime_rules_calculation_method_check check (calculation_method in ('weekly_only','greater_daily_or_weekly','daily_plus_weekly_no_double_count','special')),
  constraint overtime_rules_dates_check check (effective_to is null or effective_to >= effective_from),
  constraint overtime_rules_holiday_rule_check check (holiday_rule in ('none','reduce_weekly_threshold','count_holiday_as_hours','special')),
  constraint overtime_rules_jurisdiction_type_check check (jurisdiction_type in ('province','territory','federal')),
  constraint overtime_rules_week_start_day_check check (week_start_day between 0 and 6)
);
create unique index overtime_rules_unique_default on public.overtime_rules (province_code, effective_from)
where is_default = true and is_special_rule = false;

